        buf.readUnsignedByte(); // gsensor manager status
        buf.readUnsignedByte(); // other flags
        buf.readUnsignedByte(); // heartbeat
        buf.readUnsignedByte(); // relay status
        buf.readUnsignedShort(); // drag alarm setting

